use vstd::prelude::*;

verus! {

fn copy(arr: &Vec<i8>) -> (result: Vec<i8>)
    ensures
        result.len() == arr.len(),
        forall|i: int| 0 <= i < arr.len() ==> result[i] == arr[i],
{
    let mut out: Vec<i8> = Vec::new();
    let mut idx: usize = 0;

    while idx < arr.len()
        invariant
            idx <= arr.len(),
            out.len() == idx,
            forall|i: int| 0 <= i < idx ==> out[i] == arr[i],
        decreases
            arr.len() - idx,
    {
        out.push(arr[idx]);
        idx = idx + 1;
    }

    out
}

} // verus!

